import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models


def carry_credit_notes(apps, schema_editor):
    """Move any recorded credit note onto the companion before the columns go.

    A note with no date cannot become a row — ``received_on`` is the whole point
    of the record — so the handful of "received, date unknown" rows (if an
    install has any) are left for a person to re-enter rather than given an
    invented date.
    """
    ReturnToVendor = apps.get_model("outbound", "ReturnToVendor")
    ReturnCreditNote = apps.get_model("outbound", "ReturnCreditNote")
    for rtv in ReturnToVendor.objects.filter(
        credit_note_received=True, credit_note_date__isnull=False
    ):
        ReturnCreditNote.objects.get_or_create(
            rtv_id=rtv.pk, defaults={"received_on": rtv.credit_note_date}
        )


def return_credit_notes(apps, schema_editor):
    """Reverse: put the dates back on the documents the columns are returning to."""
    ReturnCreditNote = apps.get_model("outbound", "ReturnCreditNote")
    ReturnToVendor = apps.get_model("outbound", "ReturnToVendor")
    for note in ReturnCreditNote.objects.all():
        ReturnToVendor.objects.filter(pk=note.rtv_id).update(
            credit_note_received=True, credit_note_date=note.received_on
        )


